import csv, json, os
period = PARAMS['period']
src = INPUT_DIRS[0]
files = {'budget': f'budget_{period}.csv', 'actuals': f'gl_actuals_{period}.csv'}
need = {'budget': {'cost_center', 'account', 'budget'}, 'actuals': {'journal_id', 'cost_center', 'account', 'amount'}}
profile = {'ok': True, 'period': period}
for k, name in files.items():
    p = os.path.join(src, name)
    if not os.path.exists(p):
        profile['ok'] = False; profile[k] = f'missing: {name}'; continue
    with open(p, newline='', encoding='utf-8-sig') as f:
        r = csv.DictReader(f); rows = list(r)
    missing = sorted(need[k] - set(r.fieldnames or []))
    profile[k] = {'file': name, 'rows': len(rows), 'missing_columns': missing}
    if missing or not rows: profile['ok'] = False
open(os.path.join(OUTPUT_DIR, f'input_profile_budget_{period}.json'), 'w').write(json.dumps(profile, indent=1))
print(json.dumps(profile))

import csv, json, os
period = PARAMS['period']
pct_limit = float(PARAMS.get('threshold_pct', 10))
abs_limit = float(PARAMS.get('threshold_abs', 1000))
src = INPUT_DIRS[0]
def rows(name):
    with open(os.path.join(src, name), newline='', encoding='utf-8-sig') as f:
        return list(csv.DictReader(f))
budget = {(r['cost_center'], r['account']): float(r['budget']) for r in rows(f'budget_{period}.csv')}
gl = rows(f'gl_actuals_{period}.csv')
actual = {}
for r in gl:
    key = (r['cost_center'], r['account'])
    actual[key] = actual.get(key, 0.0) + float(r['amount'])
out = []
for key in sorted(set(budget) | set(actual)):
    b, a = budget.get(key, 0.0), round(actual.get(key, 0.0), 2)
    var = round(a - b, 2)
    pct = round(100.0 * var / b, 2) if b else None
    if not b and a:
        flag = 'unbudgeted'
    elif pct is not None and abs(pct) >= pct_limit and abs(var) >= abs_limit:
        flag = 'over' if var > 0 else 'under'
    else:
        flag = ''
    out.append([key[0], key[1], f'{b:.2f}', f'{a:.2f}', f'{var:.2f}', '' if pct is None else f'{pct:.2f}', flag])
header = ['cost_center', 'account', 'budget', 'actual', 'variance', 'variance_pct', 'flag']
for name, data in ((f'variance_{period}.csv', out), (f'variance_flags_{period}.csv', [r for r in out if r[6]])):
    with open(os.path.join(OUTPUT_DIR, name), 'w', newline='', encoding='utf-8') as f:
        w = csv.writer(f); w.writerow(header); w.writerows(data)
gl_total = round(sum(float(r['amount']) for r in gl), 2)
actual_total = round(sum(float(r[3]) for r in out), 2)
summary = {'period': period, 'threshold_pct': pct_limit, 'threshold_abs': abs_limit, 'lines': len(out),
           'flagged': sum(1 for r in out if r[6]), 'by_flag': {},
           'total_budget': round(sum(budget.values()), 2), 'total_actual': actual_total, 'gl_total': gl_total,
           'control_total_ok': abs(gl_total - actual_total) < 0.01}
for r in out:
    if r[6]: summary['by_flag'][r[6]] = summary['by_flag'].get(r[6], 0) + 1
summary['total_variance'] = round(summary['total_actual'] - summary['total_budget'], 2)
open(os.path.join(OUTPUT_DIR, f'variance_summary_{period}.json'), 'w').write(json.dumps(summary, indent=1))
print(json.dumps(summary))
